examples.template:
Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
    Column(modifier = Modifier.semantics { contentDescription = {{label}} }) {
        entries.forEach { MonarchText(text = it) }
    }
    MonarchLoadMore(
        hasMore = true,
        onLoadMore = {},
        loadedCount = entries.size,
        totalCount = {{total}},
        labels = MonarchLoadMoreLabels(
            count = { loaded, total -> "Showing $loaded of ${total ?: loaded} " + if (total == 1) {{noun.one}} else {{noun.other}} },
        ),
    )
}

